/**
 * The gate web page, served at GET / by the daemon. One self-contained HTML
 * string: no external assets, works offline, stays open in a tab via SSE.
 */

// Cropped FitGate wordmark, inlined so the page stays offline-safe (no external asset fetch).
const LOGO_DATA_URI =
  "data:image/png;base64,";

export function gateHtml(): string {
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>FitGate</title>
<link rel="icon" href="${LOGO_DATA_URI}">
<style>
  :root {
    color-scheme: dark;
    --bg-0: #08090b; --bg-1: #0e1114; --card: #13161a; --border: #22262c;
    --ink-0: #f2f4f7; --ink-1: #c3c9d1; --ink-2: #868e99; --ink-3: #565d66;
    --accent: #34d399; --accent-ink: #04140d; --accent-dim: rgba(52,211,153,.16);
    --warn: #f0b429;
  }
  * { box-sizing: border-box; }
  html, body { height: 100%; margin: 0; }
  body {
    background:
      radial-gradient(760px 420px at 50% -8%, rgba(52,211,153,.10), transparent 60%),
      radial-gradient(900px 600px at 100% 100%, rgba(80,120,255,.06), transparent 55%),
      var(--bg-0);
    color: var(--ink-0);
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Inter, Roboto, Helvetica, Arial, sans-serif;
    display: flex; flex-direction: column; align-items: center; justify-content: center;
    min-height: 100%; padding: 28px;
  }
  main { width: 100%; max-width: 520px; }
  .brand { display: block; height: 52px; width: auto; margin: 0 auto 24px; opacity: .95; }
  .card {
    background: linear-gradient(180deg, var(--card), var(--bg-1));
    border: 1px solid var(--border);
    border-radius: 24px;
    padding: 40px 36px 32px;
    text-align: center;
    box-shadow: 0 24px 60px -20px rgba(0,0,0,.6);
  }
  .agent {
    display: flex; align-items: center; gap: 8px;
    font-size: 13px; color: var(--ink-2);
    margin: 0 auto 22px; min-height: 16px; padding: 7px 14px; border-radius: 100px;
    background: rgba(255,255,255,.03); border: 1px solid var(--border);
    max-width: 100%; width: fit-content;
  }
  .agent:empty { display: none; }
  .agent .dot { width: 6px; height: 6px; border-radius: 50%; background: var(--accent); box-shadow: 0 0 0 3px var(--accent-dim); flex: none; }
  .agent .txt { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  .agent b { color: var(--ink-1); font-weight: 600; }

  .ring {
    --p: 0;
    width: 132px; height: 132px; margin: 0 auto 22px; border-radius: 50%;
    background: conic-gradient(var(--ring-color, var(--accent)) calc(var(--p) * 1%), var(--border) 0);
    display: flex; align-items: center; justify-content: center;
    transition: background .4s linear;
  }
  .ring::before {
    content: ""; position: absolute; width: 132px; height: 132px; border-radius: 50%;
  }
  .ring-inner {
    width: 110px; height: 110px; border-radius: 50%; background: var(--card);
    display: flex; flex-direction: column; align-items: center; justify-content: center;
    border: 1px solid var(--border);
  }
  .timer { font-variant-numeric: tabular-nums; font-size: 28px; font-weight: 600; color: var(--ink-0); letter-spacing: .01em; }
  .timer-label { font-size: 10px; letter-spacing: .06em; text-transform: uppercase; color: var(--ink-3); margin-top: 2px; }

  h1 { font-size: clamp(26px, 6vw, 34px); line-height: 1.2; margin: 0 0 12px; font-weight: 700; letter-spacing: -0.01em; }
  .instructions { font-size: 16px; color: var(--ink-1); margin: 0 auto 18px; max-width: 420px; line-height: 1.55; min-height: 25px; }
  .nudge {
    display: inline-block; font-style: italic; color: var(--accent); font-size: 14px;
    margin: 0 0 28px; padding: 8px 16px; border-radius: 12px; background: var(--accent-dim);
    max-width: 420px; line-height: 1.4;
  }
  .nudge:empty { display: none; margin: 0 0 6px; }

  .actions { display: flex; flex-direction: column; align-items: center; gap: 12px; }
  button { font: inherit; cursor: pointer; border: 0; border-radius: 14px; }
  .done {
    display: inline-flex; align-items: center; justify-content: center; gap: 10px;
    background: linear-gradient(180deg, #3ee2a4, var(--accent)); color: var(--accent-ink);
    font-size: 18px; font-weight: 700;
    padding: 17px 40px; width: 100%; box-shadow: 0 10px 28px -8px rgba(52,211,153,.45);
    transition: transform .08s ease, box-shadow .2s ease, opacity .15s ease;
  }
  .done:hover { transform: translateY(-1px); box-shadow: 0 14px 32px -8px rgba(52,211,153,.55); }
  .done:active { transform: translateY(1px); }
  .done:disabled, .skip:disabled { opacity: .4; cursor: default; box-shadow: none; transform: none; }
  .skip { background: transparent; color: var(--ink-3); font-size: 13px; padding: 8px 14px; }
  .skip:hover { color: var(--ink-1); }
  .kbd { font-size: 11px; opacity: .75; margin-left: 2px; }

  .clear .check {
    width: 56px; height: 56px; margin: 0 auto 18px; border-radius: 50%;
    background: var(--accent-dim); display: flex; align-items: center; justify-content: center;
    color: var(--accent);
  }
  .clear h1 { color: var(--ink-0); }

  .stats { display: grid; grid-template-columns: repeat(4, 1fr); margin-top: 28px; }
  .stats div { padding: 4px 4px; border-left: 1px solid var(--border); }
  .stats div:first-child { border-left: 0; }
  .stats b { display: block; color: var(--ink-0); font-size: 20px; font-weight: 700; letter-spacing: 0; margin-bottom: 3px; }
  .stats span { font-size: 11px; letter-spacing: .04em; text-transform: uppercase; color: var(--ink-3); }

  .foot { margin-top: 22px; font-size: 12px; color: var(--ink-3); text-align: center; }
  .foot a { color: var(--ink-2); }
  .paused { color: var(--warn); font-size: 13px; margin-top: 12px; min-height: 16px; }
  .hidden { display: none !important; }
  @keyframes pop { from { transform: scale(.97); opacity: .5 } to { transform: scale(1); opacity: 1 } }
  .pop { animation: pop .2s cubic-bezier(.2,.8,.2,1); }
  @media (max-width: 420px) { .card { padding: 32px 22px 26px; border-radius: 18px; } }
</style>
</head>
<body>
<main>
  <img class="brand" src="${LOGO_DATA_URI}" alt="FitGate" width="180" height="119">
  <div class="card">
    <div class="agent" id="agent"></div>
    <section id="gate" class="hidden">
      <div class="ring" id="ring"><div class="ring-inner"><span class="timer" id="timer">0:00</span><span class="timer-label">elapsed</span></div></div>
      <h1 id="label">…</h1>
      <p class="instructions" id="instructions"></p>
      <div class="nudge" id="nudge"></div>
      <div class="actions">
        <button class="done" id="done">Done <span aria-hidden="true">✓</span></button>
        <button class="skip" id="skip">Skip this one</button>
      </div>
    </section>
    <section id="clear" class="clear">
      <div class="check">
        <svg width="26" height="26" viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M4 12.5l5 5L20 7" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"/></svg>
      </div>
      <h1>All clear — keep coding</h1>
      <p class="instructions">The next approval prompt from your agent will open a micro-workout here.</p>
      <div class="paused" id="paused"></div>
    </section>
    <div class="stats">
      <div><b id="sCompleted">0</b><span>Done today</span></div>
      <div><b id="sServed">0</b><span>Gates</span></div>
      <div><b id="sSkipped">0</b><span>Skipped</span></div>
      <div><b id="sStreak">0</b><span>Day streak</span></div>
    </div>
  </div>
  <div class="foot">FitGate · <span id="plan">default pool</span> · <a href="/v1/status">status</a></div>
</main>
<script>
(function () {
  var $ = function (id) { return document.getElementById(id); };
  var gate = null, timerHandle = null, busy = false;

  function fmt(sec) { var m = Math.floor(sec / 60), s = sec % 60; return m + ":" + (s < 10 ? "0" : "") + s; }
  function tick() {
    if (!gate) return;
    var opened = new Date(gate.openedAt).getTime();
    var sec = Math.max(0, Math.floor((Date.now() - opened) / 1000));
    $("timer").textContent = fmt(sec);
    var expires = gate.expiresAt ? new Date(gate.expiresAt).getTime() : null;
    if (expires && expires > opened) {
      var pct = Math.min(100, Math.max(0, ((Date.now() - opened) / (expires - opened)) * 100));
      $("ring").style.setProperty("--p", String(pct));
      $("ring").style.setProperty("--ring-color", pct > 85 ? "var(--warn)" : "var(--accent)");
    }
  }
  function setStats(st) {
    if (!st) return;
    $("sCompleted").textContent = st.today.completed;
    $("sServed").textContent = st.today.gatesServed;
    $("sSkipped").textContent = st.today.skipped;
    $("sStreak").textContent = st.today.streakDays;
    $("plan").textContent = st.plan ? (st.plan.title + " v" + st.plan.version) : "default pool";
    $("paused").textContent = st.paused ? ("Paused" + (st.pausedUntil ? " until " + new Date(st.pausedUntil).toLocaleTimeString() : "") + " — gates pass through.") : "";
  }
  function render() {
    var open = gate && gate.state === "open";
    $("gate").classList.toggle("hidden", !open);
    $("clear").classList.toggle("hidden", !!open);
    if (open) {
      $("agent").innerHTML = "<span class=\\"dot\\"></span><span class=\\"txt\\"><b>" + esc(gate.agent) + "</b>" + (gate.tool ? " · " + esc(gate.tool) : "") + (gate.summary ? " · " + esc(gate.summary.slice(0, 60)) : "") + " is waiting</span>";
      $("label").textContent = gate.task.label;
      $("instructions").textContent = gate.task.instructions || "";
      $("nudge").textContent = gate.nudge || "";
      $("done").disabled = false; $("skip").disabled = false;
      document.title = "FitGate — " + gate.task.label;
      if (!timerHandle) timerHandle = setInterval(tick, 500);
      tick();
      $("gate").classList.remove("pop"); void $("gate").offsetWidth; $("gate").classList.add("pop");
    } else {
      $("agent").textContent = "";
      document.title = "FitGate";
      if (timerHandle) { clearInterval(timerHandle); timerHandle = null; }
    }
  }
  function esc(s) { return String(s).replace(/[&<>"]/g, function (c) { return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c]; }); }

  function refresh() {
    fetch("/v1/status").then(function (r) { return r.json(); }).then(function (st) {
      setStats(st); gate = st.openGate; render();
    }).catch(function () {});
  }
  function resolve(outcome) {
    if (!gate || busy) return;
    busy = true; $("done").disabled = true; $("skip").disabled = true;
    fetch("/v1/gate/" + encodeURIComponent(gate.id) + "/resolve", {
      method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ outcome: outcome })
    }).then(function () { busy = false; refresh(); }).catch(function () { busy = false; refresh(); });
  }
  $("done").addEventListener("click", function () { resolve("completed"); });
  $("skip").addEventListener("click", function () { resolve("skipped"); });
  document.addEventListener("keydown", function (e) {
    if (e.key === "Enter" && gate && gate.state === "open") resolve("completed");
  });

  function connect() {
    var es = new EventSource("/events");
    es.addEventListener("gate", function (e) { try { gate = JSON.parse(e.data); render(); refresh(); } catch (_) {} });
    es.addEventListener("resolve", function (e) { try { var g = JSON.parse(e.data); if (!gate || gate.id === g.id) { gate = g; } render(); refresh(); } catch (_) {} });
    es.addEventListener("status", function (e) { try { setStats(JSON.parse(e.data)); } catch (_) {} });
    es.onerror = function () { es.close(); setTimeout(connect, 2000); };
  }
  refresh(); connect();
  setInterval(refresh, 30000);
})();
</script>
</body>
</html>`;
}
